In Python, **everything is an object** — including **classes themselves**. A **Metaclass** is the class of a class. It controls HOW classes are created.

```
Normal OOP:     Class creates Instances
Meta OOP:       Metaclass creates Classes

type("MyClass", (object,), {}) ← type IS the default metaclass
                                  that creates ALL classes!

obj   = MyClass()      # MyClass  creates obj
MyClass = type(...)    # type     creates MyClass
```

### 🧠 Analogy:
```
COOKIE ANALOGY:
  Cookie         = Instance  (obj)
  Cookie Cutter  = Class     (MyClass)
  Cookie Cutter Factory = Metaclass  (type / custom meta)

Metaclass controls:
  → What attributes the class has
  → What methods are auto-added
  → Whether the class can be instantiated
  → Auto-registration of classes
```

```python name=metaclass_complete.py
# ══════════════════════════════════════════════════
#  METACLASSES — Complete Guide
# ══════════════════════════════════════════════════

# ─── How type() creates classes ───
# Normally you write:
class Dog:
    def bark(self): return "Woof!"

# Python ACTUALLY does:
Dog2 = type('Dog2', (object,), {'bark': lambda self: "Woof!"})

print(Dog().bark())   # Woof!
print(Dog2().bark())  # Woof! — identical!
print(type(Dog))      # <class 'type'>
print(type(42))       # <class 'int'>
print(type(type))     # <class 'type'> — type is its own metaclass!

# ─── Custom Metaclass ───
class SingletonMeta(type):
    """
    Metaclass that enforces Singleton pattern for ANY class using it.
    __call__ is triggered when you do ClassName()
    """
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            print(f"  🆕 Creating {cls.__name__} singleton")
            cls._instances[cls] = super().__call__(*args, **kwargs)
        else:
            print(f"  ♻️  Returning existing {cls.__name__} singleton")
        return cls._instances[cls]

class Database(metaclass=SingletonMeta):
    def __init__(self, host="localhost"):
        self.host        = host
        self.connections = 0

class Config(metaclass=SingletonMeta):
    def __init__(self):
        self.settings = {}

print("\n=== Singleton via Metaclass ===")
db1 = Database("prod-server")
db2 = Database("other-server")   # returns same instance!
print(f"db1 is db2: {db1 is db2}")          # True
print(f"db2.host  : {db2.host}")             # prod-server (first init)

# ─── Metaclass for Auto-Registration ───
class PluginRegistry(type):
    """
    Every class using this metaclass is auto-registered.
    No manual registration needed!
    """
    _registry = {}

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if bases:  # skip the base class itself
            plugin_name = namespace.get('plugin_name', name.lower())
            mcs._registry[plugin_name] = cls
            print(f"  📦 Auto-registered: '{plugin_name}' → {name}")
        return cls

    @classmethod
    def get_plugin(mcs, name):
        return mcs._registry.get(name)

    @classmethod
    def list_plugins(mcs):
        return list(mcs._registry.keys())

class BaseExporter(metaclass=PluginRegistry):
    def export(self, data): raise NotImplementedError

class CSVExporter(BaseExporter):
    plugin_name = "csv"
    def export(self, data):
        return f"CSV: {','.join(str(d) for d in data)}"

class JSONExporter(BaseExporter):
    plugin_name = "json"
    def export(self, data):
        import json
        return json.dumps(data)

class XMLExporter(BaseExporter):
    plugin_name = "xml"
    def export(self, data):
        return f"<data>{''.join(f'<item>{d}</item>' for d in data)}</data>"

print("\n=== Auto-Registration via Metaclass ===")
print(f"Registered plugins: {PluginRegistry.list_plugins()}")
exporter = PluginRegistry.get_plugin("csv")([1,2,3])  # dynamic!
# Better:
for name in PluginRegistry.list_plugins():
    plugin_cls = PluginRegistry.get_plugin(name)
    result     = plugin_cls().export([1, 2, 3])
    print(f"  {name}: {result}")

# ─── Metaclass for API Validation ───
class ValidatedMeta(type):
    """
    Ensures all public methods in a class have type hints.
    Enforces coding standards at class DEFINITION time.
    """
    def __new__(mcs, name, bases, namespace):
        import inspect
        for attr_name, attr_val in namespace.items():
            if callable(attr_val) and not attr_name.startswith('_'):
                hints = getattr(attr_val, '__annotations__', {})
                if 'return' not in hints:
                    raise TypeError(
                        f"❌ {name}.{attr_name}() is missing return type hint!"
                    )
        return super().__new__(mcs, name, bases, namespace)

print("\n=== ValidatedMeta ===")
try:
    class BadAPI(metaclass=ValidatedMeta):
        def get_user(self, user_id: int):    # missing -> return hint!
            return {}
except TypeError as e:
    print(e)

class GoodAPI(metaclass=ValidatedMeta):
    def get_user(self, user_id: int) -> dict:    # ✅ has return hint
        return {"id": user_id}
    def create_user(self, data: dict) -> bool:   # ✅
        return True

print("GoodAPI created successfully!")
```
